<script setup lang="ts">
import { ref,nextTick } from 'vue'
import { onLoad,onShow,onHide,onUnload } from '@dcloudio/uni-app'
import { request,idempotencyKey,statuses,date } from '../../api'
import { useSession } from '../../stores/session'
import { supportEvents,supportStates } from '../../support-api'
const auth=useSession(),current=ref<any>(null),messages=ref<any[]>([]),history=ref<any[]>([]),communities=ref<any[]>([]),faq=ref<any[]>([]),orders=ref<any[]>([]),orderPage=ref(1),orderTotal=ref(0),historyPage=ref(1),historyTotal=ref(0)
const community=ref(''),orderId=ref(''),text=ref(''),busy=ref(false),error=ref(''),card=ref<any>(null),actions=ref<string[]>([]),scrollTo=ref(''),starting=ref(true)
let cursor=0,generation=0,active=true,cancel:(()=>void)|undefined,retry:ReturnType<typeof setTimeout>|undefined,initialId='',initialOrder='',attempt:{content:string,id:string}|null=null
onLoad(o=>{initialId=String(o?.id||'');initialOrder=String(o?.orderId||'')})
onShow(async()=>{active=true;if(!auth.requireLogin())return;try{communities.value=(await request('/support/options')).communities;await histories();if(current.value)await select(current.value.id);else if(initialId){await select(initialId);initialId=''}else if(initialOrder){orderId.value=initialOrder;initialOrder='';await create()}else await knowledge()}catch{error.value='加载失败，请返回后重试'}})
function stop(){active=false;generation++;cancel?.();if(retry)clearTimeout(retry)}
onHide(stop);onUnload(stop)
async function histories(more=false){if(!more)historyPage.value=1;else historyPage.value++;const r=await request('/support/sessions','GET',{page:historyPage.value});history.value=more?[...history.value,...r.records]:r.records;historyTotal.value=r.total}
async function knowledge(){faq.value=await request('/support/knowledge','GET',community.value?{communityId:community.value}:{})}
async function loadOrders(more=false){if(!more)orderPage.value=1;else orderPage.value++;const r=await request('/repair/orders','GET',{page:orderPage.value,size:20});orders.value=more?[...orders.value,...r.records]:r.records;orderTotal.value=r.total}
async function create(){if(busy.value)return;busy.value=true;try{const s=await request('/support/sessions','POST',{role:auth.activeRole,communityId:community.value||null,orderId:orderId.value||null});await select(s.id);await histories()}finally{busy.value=false}}
async function select(id:string){generation++;cancel?.();if(retry)clearTimeout(retry);const g=generation;error.value='';const r=await request(`/support/sessions/${id}`);if(g!==generation||!active)return;current.value=r.session;card.value=r.order;actions.value=r.actions;messages.value=[];cursor=0;text.value='';attempt=null;starting.value=false;poll(g)}
async function poll(g:number){if(!active||g!==generation||!current.value)return;const id=current.value.id;const p=supportEvents(id,cursor);cancel=p.cancel;try{const r=await p.promise;if(g!==generation||!active)return;current.value=r.session;card.value=r.order;actions.value=r.actions;const seen=new Set(messages.value.map(m=>m.id));messages.value.push(...r.messages.filter((m:any)=>!seen.has(m.id)));cursor=Number(r.cursor);error.value='';if(r.messages.length){await nextTick();scrollTo.value='message-'+messages.value[messages.value.length-1]?.id;await request(`/support/sessions/${id}/read`,'POST',{seq:cursor})}retry=setTimeout(()=>poll(g),50)}catch(e:any){if(g!==generation||!active)return;error.value=e.status===401?'登录已失效':e.status===403||e.status===404?'会话已不可访问，请返回咨询列表':'连接中断，正在重新连接…';if(![401,403,404].includes(e.status))retry=setTimeout(()=>poll(g),2000)}}
async function send(content=text.value){if(!content.trim()||busy.value||!current.value)return;busy.value=true;const value=content.trim();if(!attempt||attempt.content!==value)attempt={content:value,id:idempotencyKey()};try{await request(`/support/sessions/${current.value.id}/messages`,'POST',{clientId:attempt.id,content:value});text.value='';attempt=null}catch{error.value='发送失败，内容已保留；再次发送可重试'}finally{busy.value=false}}
async function act(name:string){if(busy.value)return;busy.value=true;try{current.value=await request(`/support/sessions/${current.value.id}/${name}`,'POST',{version:current.value.version});await histories()}catch{const r=await request(`/support/sessions/${current.value.id}`);current.value=r.session}finally{busy.value=false}}
function newChat(){generation++;cancel?.();current.value=null;starting.value=true;messages.value=[];text.value='';error.value='';orderId.value='';knowledge()}
function navigate(action:string){if(action==='HUMAN')return act('handoff');const path=action==='CREATE_REPAIR'?'/pages/create/index':action==='BIND_ROOM'?'/pages/bindings/index':card.value?`/pages/detail/index?id=${card.value.id}`:'';if(path)uni.navigateTo({url:path})}
</script>
<template><view class="page support"><view class="eyebrow">COMMUNITYFIX · 客服</view><view class="row"><view class="page-title">有问题，慢慢说。</view><text class="link" @click="newChat">新咨询</text></view>
<view v-if="error" class="error">{{error}}</view>
<template v-if="starting"><view class="card"><view class="label">咨询哪个小区</view><picker :range="[{id:'',name:'平台客服'},...communities]" range-key="name" @change="community=[{id:'',name:'平台客服'},...communities][Number($event.detail.value)].id;knowledge()"><view class="field">{{communities.find(c=>c.id===community)?.name||'平台客服（无所属小区）'}}</view></picker><view class="label">关联工单（可选）</view><button class="secondary" @click="loadOrders()">选择我的工单</button><picker v-if="orders.length" :range="[{id:'',orderNo:'不关联工单'},...orders]" range-key="orderNo" @change="orderId=[{id:'',orderNo:''},...orders][Number($event.detail.value)].id"><view class="field">{{orders.find(o=>o.id===orderId)?.orderNo||'不关联工单'}}</view></picker><text v-if="orders.length<orderTotal" class="link" @click="loadOrders(true)">更多工单</text><view class="small muted">关联工单后，咨询将交给该工单所属小区。</view><button class="primary" :loading="busy" :disabled="busy" @click="create">开始咨询</button></view>
<view class="section-title">常见问题</view><view v-if="!faq.length" class="muted">暂无已发布问答，可以开始咨询或转人工。</view><view v-for="k in faq" :key="k.id" class="card"><view class="order-title">{{k.question}}</view><view class="answer">{{k.answer}}</view></view>
<view class="section-title">历史咨询</view><view v-if="!history.length" class="muted">还没有咨询记录。</view><view v-for="s in history" :key="s.id" class="history" @click="select(s.id)"><text>{{s.communityName||'平台客服'}} · {{supportStates[s.status]}}</text><text class="small">{{date(s.updatedAt)}} {{Number(s.unread)>0?'· 有未读':''}}</text></view><button v-if="history.length<historyTotal" class="secondary" @click="histories(true)">更多记录</button></template>
<template v-else-if="current"><view class="status-strip"><text>{{supportStates[current.status]}}</text><text class="small">{{current.communityId?'小区服务':'平台服务'}}</text></view><view v-if="current.status==='WAITING'" class="notice">暂未接入人工客服，留言会保留；接入或回复后会收到站内消息。</view>
<view v-if="card" class="order-card" @click="navigate('ORDER_DETAIL')"><view>{{card.orderNo}} · {{statuses[card.status]}}</view><view class="small">最近更新 {{date(card.updatedAt)}}　查看工单 →</view></view>
<scroll-view class="conversation" scroll-y :scroll-into-view="scrollTo"><view v-for="m in messages" :id="'message-'+m.id" :key="m.id" :class="['bubble',m.senderType.toLowerCase()]"><view class="small">{{m.senderType==='USER'?'我':m.senderType==='AGENT'?'人工客服':m.senderType==='AI'?(m.metadata?.source==='AI'?'AI 客服':'客服指引'):'服务提示'}} · {{date(m.createdAt)}}</view><view class="answer">{{m.content}}</view><view v-for="k in m.metadata?.citations||[]" :key="k.id" class="citation"><view>参考 · {{k.title}}</view><view class="answer">{{k.answer}}</view></view></view></scroll-view>
<view class="chat-actions"><button v-if="current.status==='AI'" size="mini" @click="act('handoff')">转人工</button><button v-if="current.status==='WAITING'" size="mini" @click="act('cancel-wait')">取消排队</button><button v-if="actions.includes('CREATE_REPAIR')" size="mini" @click="navigate('CREATE_REPAIR')">提交报修</button><button v-if="actions.includes('BIND_ROOM')" size="mini" @click="navigate('BIND_ROOM')">房屋绑定</button><button v-if="current.status!=='CLOSED'" size="mini" @click="act('close')">结束咨询</button></view>
<view v-if="current.status!=='CLOSED'" class="composer"><textarea v-model="text" maxlength="2000" placeholder="输入你的问题，最多2000字" :disabled="busy"/><button class="primary" :loading="busy" :disabled="busy||!text.trim()" @click="send()">发送</button></view><view v-else class="notice">会话已结束，历史记录将保留 90 天。需要继续咨询时点击“新咨询”。</view></template></view></template>
<style scoped>
.support{padding-bottom:40rpx}.page-title{font-size:40rpx}.status-strip{display:flex;justify-content:space-between;background:#0b5354;color:#fff;padding:24rpx;border-radius:16rpx;margin:24rpx 0}.conversation{height:48vh}.bubble{margin:20rpx 36rpx 20rpx 0;padding:24rpx;background:#fff;border-radius:0 20rpx 20rpx 20rpx;word-break:break-word}.bubble.user{margin:20rpx 0 20rpx 36rpx;background:#dbeeea;border-radius:20rpx 0 20rpx 20rpx}.bubble.system{background:transparent;color:#607d7f;padding:10rpx;font-size:24rpx}.answer{white-space:pre-wrap;line-height:1.8;margin-top:8rpx}.citation{border-left:4rpx solid #91b9b1;padding-left:18rpx;margin-top:18rpx;font-size:24rpx}.order-card{padding:20rpx;border:1px solid #b9d6d0;border-radius:14rpx}.chat-actions{display:flex;gap:10rpx;flex-wrap:wrap;margin:20rpx 0}.chat-actions button{margin:0;color:#0b5354}.composer textarea{box-sizing:border-box;width:100%;height:150rpx;padding:20rpx;background:#fff;border:1px solid #b9d6d0;border-radius:12rpx}.history{display:flex;flex-direction:column;gap:10rpx;padding:28rpx 0;border-bottom:1px solid #dbe5e5}
</style>
